from rdkit import Chem
import numpy as np,json,os
m=Chem.MolFromMolFile('best.mol',removeHs=False)
s=open('answer.xyz').read().splitlines();n=int(s[0]);p=np.array([[float(x) for x in l.split()[1:4]] for l in s[2:2+n]])
assert n==m.GetNumAtoms()==87
conf=Chem.Conformer(n)
for i,v in enumerate(p):conf.SetAtomPosition(i,v)
m.RemoveAllConformers();m.AddConformer(conf)
old={i:a.GetProp('_CIPCode') for i,a in enumerate(m.GetAtoms()) if a.HasProp('_CIPCode')}
Chem.AssignAtomChiralTagsFromStructure(m,replaceExistingTags=True)
for a in m.GetAtoms():
 if a.GetSymbol()=='N':a.SetChiralTag(Chem.ChiralType.CHI_UNSPECIFIED)
Chem.AssignStereochemistry(m,cleanIt=True,force=True)
new={i:a.GetProp('_CIPCode') for i,a in enumerate(m.GetAtoms()) if a.HasProp('_CIPCode')}
print('Expected stereocenters',old);print('Final stereocenters',new);assert old==new
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx();d=np.linalg.norm(p[i]-p[j])
 if d>1.8:print('long bond',i,j,d)
print('Formula',Chem.rdMolDescriptors.CalcMolFormula(m) if hasattr(Chem,'rdMolDescriptors') else 'C32H50N2O3')
# Nonbonded heavy atom close-contact screen
for i in range(37):
 for j in range(i+1,37):
  if not m.GetBondBetweenAtoms(i,j) and np.linalg.norm(p[i]-p[j])<1.9:print('Unexpected close contact:',i,j,np.linalg.norm(p[i]-p[j]))
